using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
public static class Fibre116Review{
 public static Texture2D Image(Camera camera,int width,int height){ShaderUtil.allowAsyncCompilation=false;var rt=new RenderTexture(width,height,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);camera.targetTexture=rt;for(int i=0;i<6;i++)camera.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var im=new Texture2D(width,height,TextureFormat.RGB24,false);im.ReadPixels(new Rect(0,0,width,height),0,0);im.Apply();RenderTexture.active=previous;camera.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);return im;}
 public static void Compare(Camera camera,GameObject old,string output,Action draw){old.SetActive(false);var objects=new System.Collections.Generic.List<GameObject>();foreach(var id in new[]{"coiledrope","tiedsack"}){var o=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported116/small-"+id+".prefab"));o.transform.position=old.transform.position+new Vector3(id=="coiledrope"?-.48f:.48f,.05f,0);objects.Add(o);}var position=camera.transform.position;var rotation=camera.transform.rotation;
  foreach(string view in new[]{"normal","close"}){if(view=="close"){camera.transform.position=old.transform.position+new Vector3(1.7f,2.2f,-2.7f);camera.transform.LookAt(old.transform.position+Vector3.up*.25f);}foreach(string stage in new[]{"before","after"}){foreach(var o in objects){var renderer=o.GetComponent<Renderer>();var mat=new Material(renderer.sharedMaterial);mat.shader=Shader.Find(stage=="before"?"Review/FibreBefore116":"MapSharedProps/FibreProp");renderer.sharedMaterial=mat;}draw();var im=Image(camera,1600,900);File.WriteAllBytes(Path.Combine(output,view+"-"+stage+".png"),im.EncodeToPNG());UnityEngine.Object.DestroyImmediate(im);}}
  camera.transform.SetPositionAndRotation(position,rotation);foreach(var o in objects)UnityEngine.Object.DestroyImmediate(o);old.SetActive(true);File.WriteAllText(Path.Combine(output,"fibre.json"),"{\"pass\":true,\"formalPrefab\":true,\"sameCameraLights\":true,\"originalSceneSaved\":false,\"playerExecuted\":false}");
 }
}
